// ===== CONFIG =====
const AUTO_SEND_ENABLED = true; // true = send reply automatically; false = save as Gmail draft for review
const REQUIRED_CONTACT = 'fa23-bscs-184@cs.lgu.edu.pk'; // every reply must contain this
// ==================
const INTENTS = ['service_inquiry','technical_question','pricing','project_request','existing_client_support','complaint','spam','marketing','other'];
const LEADS = ['new','qualified','existing_customer','not_a_lead','unknown'];
const REQUIRED = ['reply_required','auto_send','human_review','intent','lead_status','reason','reply_subject','reply_body'];
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const mail = $('Normalize Email').itemMatching(i).json;
  const errors = [];
  let r = {};
  const raw = String(items[i].json.text || '').trim();
  try {
    r = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
  } catch (e) {
    errors.push('invalid_json');
  }
  for (const k of REQUIRED) { if (!(k in r)) errors.push('missing_' + k); }
  if (!INTENTS.includes(r.intent)) errors.push('bad_intent');
  if (!LEADS.includes(r.lead_status)) errors.push('bad_lead_status');
  const replyRequired = r.reply_required === true;
  const humanReview = r.human_review === true;
  let autoSend = r.auto_send === true;
  if (!replyRequired || humanReview) autoSend = false;
  const body = String(r.reply_body || '').trim();
  let subject = String(r.reply_subject || '').trim();
  if (!subject) subject = 'Re: ' + mail.subject;
  if (replyRequired) {
    if (!body) errors.push('empty_body');
    const hasBracketPlaceholder = body.split('[').slice(1).some(s => {
      const t = s.split(']')[0];
      return s.includes(']') && t === t.toUpperCase() && /[A-Z]/.test(t);
    });
    if (hasBracketPlaceholder || body.includes('YOUR_') || body.includes('{{')) errors.push('placeholder_in_reply');
    if (!body.toLowerCase().includes(REQUIRED_CONTACT.toLowerCase())) errors.push('missing_contact_email');
    if (body.split(' ').length > 200) errors.push('reply_too_long');
  }
  let route = 'draft';
  if (errors.length) route = 'error';
  else if (!replyRequired || r.intent === 'spam') route = 'skip';
  else if (autoSend && AUTO_SEND_ENABLED) route = 'send';
  out.push({ json: {
    route,
    errors,
    messageId: mail.id,
    threadId: mail.threadId,
    fromEmail: mail.fromEmail,
    reply_required: replyRequired,
    auto_send: autoSend,
    human_review: humanReview,
    intent: r.intent || '',
    lead_status: r.lead_status || '',
    reason: r.reason || '',
    reply_subject: subject,
    reply_body: body
  } });
}
return out;
